pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep the domain wide; only exclude degenerate actor
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // deploy a functioning log and register it via SetLogFile (before Initialized)
        EchoLog log = new EchoLog();
        address(c).call(abi.encodeWithSignature("SetLogFile(address)", address(log)));

        // funded actor deposits through the payable entry
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }

        // General rule: once a valid, code-carrying log has been set via SetLogFile,
        // Deposit by any funded actor must succeed (the log call is well-formed).
        // In the mutant Log remains address(0); Solidity's extcodesize guard makes
        // the internal log call in Deposit revert, so ok == false.
        assertTrue(ok);
    }
}

// minimal functioning log whose AddMessage ABI-matches LogFile.AddMessage
contract EchoLog {
    function AddMessage(address, uint256, string calldata) external pure {}
}
}

