pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        // Point the log at C itself: C has no AddMessage selector, so any
        // deposit that really routes through the stored Log must revert.
        c.SetLogFile(address(c));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: Deposit routes through Log == c, whose AddMessage is
        // missing, so it always reverts. Mutant: Log stays address(0), the
        // no-code call succeeds, so Deposit succeeds and this assertion fails.
        assertTrue(!ok);
    }
}

