pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HistLog log;

    function setUp() public {
        c = new C();
        log = new HistLog();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(log) && actor != address(c));
        vm.prank(actor);
        c.SetLogFile(address(log));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Deposit{value: 1 ether}();
        bool recorded;
        try log.History(0) returns (address sender, string memory, uint256, uint256) {
            recorded = (sender == actor);
        } catch {
            recorded = false;
        }
        assertTrue(recorded);
    }
}

contract HistLog {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }

    Message[] public History;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        History.push(Message(_adr, _data, _val, block.timestamp));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function check(uint256 a, uint256 b) public {
        c.SetMinSum(0);
        require(address(this).balance >= a + b);
        c.Deposit{value: a}();
        c.Deposit{value: b}();
        // In P, balance is a+b, so collecting more than a+b is disallowed;
        // in M, balance is only b, so collecting a+b succeeds and no revert occurs.
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", a + b + 1));
        assert(ok == false);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
    C c;
    constructor(C _c) { c = _c; }

    function test(uint v1, uint v2) public
    {
        require(v1 != v2);
        c.SetMinSum(v1);
        c.Initialized();
        c.SetMinSum(v2);
        assert(c.MinSum() == v1);
    }
}
